<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {getStagingClients} from '../integrations/firebase/stagingClient'
import {mayWriteLive} from '../integrations/firebase/stagingConfig'
import {watchMulti,saveMulti,archiveMulti} from '../integrations/firestore/multisport'
import {SPORTS,TYPES,STYLES,FIELDS,ALLOWED,REQUIRED,blank,today,seconds,timeLabel,numberLabel,valueLabel,metrics,metricValue,metricText,metricLabel,seriesKey,comparable,lower,type Sport,type Result,type ResultData,type NumberField,type Metric} from '../features/multisport/model'
const props=defineProps<{gym:string;athlete:string;actor:string;role:'athlete'|'coach'}>()
const selected=ref<Sport|null>(null), tab=ref<'history'|'graph'>('history'), rows=ref<Result[]>([]), pageSize=ref(100),more=ref(false),loading=ref(true),connection=ref(false),error=ref(''),notice=ref(''),busy=ref(false),form=ref<ResultData|null>(null),editing=ref<Result|null>(null),confirmArchive=ref<Result|null>(null),showArchived=ref(false),search=ref(''),openId=ref('')
const distanceUnit=ref('m'), distanceInput=ref(''),hour=ref(''),minute=ref(''),sec=ref(''),cent=ref(''),metric=ref<Metric>('durationSec'),group=ref(''),pointId=ref('')
let active=true,unsubscribe:(()=>void)|undefined, generation=0
const canWrite=computed(()=>connection.value&&mayWriteLive()&&!busy.value&&getStagingClients().auth.currentUser?.uid===props.actor)
function bind(){unsubscribe?.();const token=++generation;loading.value=true;error.value='';connection.value=false;unsubscribe=watchMulti(getStagingClients().db,props.gym,props.athlete,pageSize.value,(list,cached,hasMore)=>{if(!active||token!==generation)return;if(cached){connection.value=false;return}if(getStagingClients().auth.currentUser?.uid!==props.actor){rows.value=[];connection.value=false;return}rows.value=list;more.value=hasMore;loading.value=false;connection.value=true;error.value=''},()=>{if(!active||token!==generation)return;rows.value=[];connection.value=false;loading.value=false;error.value='Risultati non disponibili. Controlla la connessione o le autorizzazioni.'})}
onMounted(()=>{try{bind()}catch{loading.value=false;error.value='Connessione non disponibile.'}})
onUnmounted(()=>{active=false;generation++;unsubscribe?.()})
const sportInfo=computed(()=>SPORTS.find(s=>s.id===selected.value))
const current=computed(()=>rows.value.filter(r=>r.sport===selected.value))
const visible=computed(()=>current.value.filter(r=>r.archived===showArchived.value&& [r.testName,r.disciplineName,r.kind,r.style].join(' ').toLocaleLowerCase('it').includes(search.value.trim().toLocaleLowerCase('it'))))
const choices=computed(()=>selected.value?metrics(selected.value):[])
const groups=computed(()=>{const m=metric.value;const map=new Map<string,Result>();for(const r of current.value)if(!r.archived&&metricValue(r,m)!==null)map.set(seriesKey(r,m),r);return [...map.entries()]})
watch(groups,g=>{if(!g.some(([k])=>k===group.value))group.value=g[0]?.[0]||''})
const example=computed(()=>groups.value.find(([k])=>k===group.value)?.[1])
const points=computed(()=>example.value?comparable(current.value,example.value,metric.value).map(r=>({r,v:metricValue(r,metric.value)!})):[])
const best=computed(()=>example.value&&points.value.length? (lower(example.value,metric.value)?Math.min(...points.value.map(p=>p.v)):Math.max(...points.value.map(p=>p.v))):null)
const plot=computed(()=>{const vals=points.value.map(p=>p.v),lo=Math.min(...vals),hi=Math.max(...vals),span=hi-lo||1;return points.value.map((p,i)=>({x:30+(vals.length===1?135:i*270/(vals.length-1)),y:145-(hi===lo?.5:(p.v-lo)/span)*110,p}))})
const plotting=computed(()=>plot.value.map(p=>`${p.x},${p.y}`).join(' '))
const chosenPoint=computed(()=>points.value.find(p=>p.r.id===pointId.value)||null)
watch([metric,group],()=>{pointId.value=''})
const fmt=(r:ResultData,m:Metric,v:number)=>metricText(r,m,v)
function selectSport(s:Sport){selected.value=s;tab.value='history';search.value='';showArchived.value=false;openId.value='';form.value=null;editing.value=null;confirmArchive.value=null;metric.value=metrics(s)[0];group.value='';notice.value=''}
function newForm(r?:Result){if(!selected.value)return;editing.value=r||null;form.value=r?Object.fromEntries(Object.keys(blank(r.sport)).map(k=>[k,r[k as keyof ResultData]])) as ResultData:blank(selected.value);distanceUnit.value=selected.value==='cycle'?'km':'m';distanceInput.value=r?.distanceM==null?'':String(r.distanceM/(distanceUnit.value==='km'?1000:1));const v=r?.durationSec==null?null:Math.round(r.durationSec*100);hour.value=v===null?'':String(Math.floor(v/360000));minute.value=v===null?'':String(Math.floor(v/6000)%60);sec.value=v===null?'':String(Math.floor(v/100)%60);cent.value=v===null?'':String(v%100);error.value='';notice.value='';confirmArchive.value=null}
const otherFields=computed(()=>form.value?ALLOWED[form.value.sport].filter(k=>!['distanceM','poolM','durationSec'].includes(k)):[])
const allows=(k:NumberField)=>!!form.value&&ALLOWED[form.value.sport].includes(k)
const required=(k:NumberField)=>!!form.value&&REQUIRED[form.value.sport].includes(k)
const inputNumber=(k:NumberField,e:Event)=>{if(form.value){const s=(e.target as HTMLInputElement).value;form.value[k]=s===''?null:Number(s)}}
const computedDistance=computed(()=>{if(distanceInput.value==='')return null;return Number(distanceInput.value)*(distanceUnit.value==='km'?1000:distanceUnit.value==='laps'?(form.value?.poolM??0):1)})
const computedTime=computed(()=>{try{return seconds(hour.value,minute.value,sec.value,cent.value)}catch{return null}})
function groupName(r:Result){return [r.disciplineName,r.testName,r.kind,r.style,r.distanceM!==null?numberLabel(r.distanceM)+' m':'',r.poolM!==null?'Piscina '+numberLabel(r.poolM)+' m':'',r.sport==='cycle'&&r.elevationM!==null?'D+ '+r.elevationM+' m':'',r.sport==='fight'&&r.roundSec!==null?'Round '+r.roundSec+' s':'',r.sport==='fight'&&r.restSec!==null?'Rec. '+r.restSec+' s':'',r.sport==='crossfit'&&metric.value!=='loadKg'&&r.loadKg!==null?r.loadKg+' kg':'',r.sport==='crossfit'&&['AMRAP','EMOM'].includes(r.kind)&&r.durationSec!==null?timeLabel(r.durationSec):'',r.customUnit,r.direction==='lower'?'↓':r.direction==='higher'?'↑':''].filter(Boolean).join(' · ')}
function primary(r:Result){const m=metrics(r.sport).find(m=>metricValue(r,m)!==null);return m?fmt(r,m,metricValue(r,m)!):'—'}
async function submit(){if(!form.value||!canWrite.value)return;busy.value=true;error.value='';notice.value='';try{const r={...form.value,distanceM:allows('distanceM')?computedDistance.value:null,durationSec:allows('durationSec')?seconds(hour.value,minute.value,sec.value,cent.value):null};if(distanceUnit.value==='laps'&&(!Number.isInteger(Number(distanceInput.value))||!r.poolM))throw Error('Indica un numero intero di vasche e la lunghezza piscina.');await saveMulti(getStagingClients().db,props.gym,props.athlete,props.actor,r,editing.value||undefined);if(active){form.value=null;editing.value=null;notice.value='Risultato salvato.';tab.value='history'}}catch(e){if(active)error.value=e instanceof Error?e.message:'Salvataggio non riuscito.'}finally{if(active)busy.value=false}}
async function archive(){const r=confirmArchive.value;if(!r||!canWrite.value)return;busy.value=true;error.value='';try{await archiveMulti(getStagingClients().db,props.gym,props.athlete,props.actor,r);if(active){confirmArchive.value=null;notice.value=r.archived?'Risultato ripristinato.':'Risultato archiviato.'}}catch(e){if(active)error.value=e instanceof Error?e.message:'Operazione non riuscita.'}finally{if(active)busy.value=false}}
const art:Record<Sport,string>={swim:'M7 53c12-13 21 13 33 0s21 13 33 0 21 13 33 0M7 65c12-13 21 13 33 0s21 13 33 0 21 13 33 0M34 43l25-16 23 17M60 27 46 12 24 18M78 23a8 8 0 1 0 0-16 8 8 0 0 0 0 16',run:'M65 23a9 9 0 1 0 0-18 9 9 0 0 0 0 18M58 27 43 48l25 7 13 18M43 48 27 69 8 69M58 27l20 12 21-9M53 33 32 29 17 42M8 20h23M2 82h109',cycle:'M27 73a20 20 0 1 0 0-40 20 20 0 0 0 0 40M88 73a20 20 0 1 0 0-40 20 20 0 0 0 0 40M27 53 48 22l18 31H27l27-21h22l12 21M39 22h15M72 16h12',fight:'M22 43V24c0-11 19-17 29-8l4 9v23l-10 11H29zM29 59v13h18V59M65 43V23c0-11 19-17 29-8l5 10v23L89 59H72zM72 59v13h18V59M26 33h23M69 33h24',crossfit:'M7 38h105M18 19v38M29 12v52M91 12v52M102 19v38M49 38l10 29 10-29M44 67h30',custom:'M15 66V17M15 66h90M27 52l20-18 17 8 32-29M81 13h15v15M49 82h34M66 71v22'}
</script>
<template>
 <section class="lf-ms stack" aria-label="Advanced Progress MultiSport">
  <div class="lf-ms-head"><div><span class="eyebrow">ADVANCED PROGRESS</span><h2>Altri progressi</h2><p class="muted small">Risultati sportivi e test atletici</p></div><span class="lf-ms-symbol">↗</span></div>
  <p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
  <p v-if="loading&&!connection" class="muted small" role="status">In attesa dei dati dal server… <button type="button" class="secondary" @click="bind">Riprova</button></p><p v-else-if="!connection&&!error" class="muted small">Connessione non disponibile: modifica sospesa. <button type="button" class="secondary" @click="bind">Riprova</button></p>
  <div v-if="!selected" class="lf-ms-sports"><button v-for="s in SPORTS" :key="s.id" :style="{'--sport-color':s.color}" class="lf-ms-sport" type="button" @click="selectSport(s.id)"><svg viewBox="0 0 120 95" aria-hidden="true"><path :d="art[s.id]" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg><span class="lf-ms-sport-copy"><b>{{s.name}}</b><small>{{s.desc}}</small><small>{{rows.filter(r=>r.sport===s.id&&!r.archived).length}} risultati caricati ›</small></span></button></div>
  <template v-else>
   <div class="row between"><button type="button" class="secondary" :disabled="busy" @click="selected=null;form=null;confirmArchive=null">← Discipline</button><b>{{sportInfo?.name}}</b></div>
   <button v-if="!form" type="button" class="primary wide" :disabled="!canWrite" @click="newForm()">+ Registra risultato</button>
   <form v-if="form" class="panel lf-ms-panel" @submit.prevent="submit">
    <div class="row between"><h3>{{editing?'Modifica risultato':'Nuovo risultato'}}</h3><button type="button" class="secondary" :disabled="busy" @click="form=null;editing=null">Chiudi</button></div>
    <label v-if="form.sport==='custom'">Disciplina <input v-model="form.disciplineName" required maxlength="60" placeholder="es. Atletica"/></label>
    <label>Nome test <input v-model="form.testName" required maxlength="100" placeholder="es. Test 100 m / WOD Fran" list="lf-ms-existing"/></label><datalist id="lf-ms-existing"><option v-for="name in [...new Set(current.map(r=>r.testName))]" :key="name" :value="name"/></datalist>
    <div class="lf-ms-fields"><label>Data <input v-model="form.performedOn" required type="date" :max="today()"/></label><label>Tipo <select v-model="form.kind"><option v-for="t in TYPES[form.sport]" :key="t">{{t}}</option></select></label></div>
    <div v-if="form.sport==='swim'" class="lf-ms-fields"><label>Stile <select v-model="form.style"><option v-for="s in STYLES" :key="s">{{s}}</option></select></label><label>Piscina (m) <input type="number" required min="1" max="200" step=".01" :value="form.poolM??''" @input="inputNumber('poolM',$event)" list="lf-ms-pools" placeholder="25 / 50"/><datalist id="lf-ms-pools"><option value="25"/><option value="50"/></datalist></label></div>
    <div v-if="allows('distanceM')" class="lf-ms-fields"><label>Distanza <input v-model="distanceInput" type="number" :required="required('distanceM')" :min="distanceUnit==='laps'?1:.001" :step="distanceUnit==='laps'?1:'any'"/></label><label>Unità <select v-model="distanceUnit"><option value="m">Metri</option><option v-if="form.sport!=='swim'" value="km">Chilometri</option><option v-if="form.sport==='swim'" value="laps">Vasche</option></select></label></div>
    <p v-if="form.sport==='swim'&&computedDistance&&form.poolM" class="muted small">{{numberLabel(computedDistance)}} m · {{numberLabel(computedDistance/form.poolM)}} vasche</p>
    <fieldset v-if="allows('durationSec')" class="lf-ms-time"><legend>Tempo {{required('durationSec')?'*':''}}</legend><div><label>Ore<input v-model="hour" type="number" min="0" max="168" placeholder="0"/></label><label>Min<input v-model="minute" type="number" min="0" max="59" placeholder="00"/></label><label>Sec<input v-model="sec" type="number" min="0" max="59" placeholder="00"/></label><label>Cent.<input v-model="cent" type="number" min="0" max="99" placeholder="00"/></label></div></fieldset>
    <p v-if="computedDistance&&computedTime&&['swim','run','cycle'].includes(form.sport)" class="lf-ms-preview">{{form.sport==='swim'?timeLabel(computedTime*100/computedDistance)+' /100 m':form.sport==='run'?timeLabel(computedTime*1000/computedDistance)+' /km':numberLabel(computedDistance/computedTime*3.6)+' km/h'}}</p>
    <div v-if="form.sport==='custom'" class="lf-ms-fields"><label>Unità risultato<input v-model="form.customUnit" required maxlength="24" placeholder="cm, punti…"/></label><label>Migliora se<select v-model="form.direction"><option value="higher">Aumenta ↑</option><option value="lower">Diminuisce ↓</option></select></label></div>
    <div class="lf-ms-fields"><label v-for="k in otherFields" :key="k">{{FIELDS[k].label}}{{FIELDS[k].unit?' ('+FIELDS[k].unit+')':''}} <input type="number" :required="required(k)" :min="FIELDS[k].min" :max="FIELDS[k].max" :step="FIELDS[k].step" :value="form[k]??''" @input="inputNumber(k,$event)"/></label></div>
    <label>Note facoltative<textarea v-model="form.notes" maxlength="1000" rows="2"/></label><button class="primary wide" type="submit" :disabled="!canWrite">{{busy?'Salvataggio…':'Salva risultato'}}</button>
   </form>
   <div class="lf-ms-tabs" role="group" aria-label="Vista risultati"><button type="button" :class="{on:tab==='history'}" @click="tab='history'">Storico dati</button><button type="button" :class="{on:tab==='graph'}" @click="tab='graph'">Grafici</button></div>
   <template v-if="tab==='history'"><input v-model="search" type="search" placeholder="Cerca test…" aria-label="Cerca test"/><label class="checkline"><input v-model="showArchived" type="checkbox"/> Mostra risultati archiviati</label><p v-if="!visible.length&&!loading" class="muted small">Nessun risultato in questa vista.</p><article v-for="r in visible" :key="r.id" class="panel lf-ms-panel lf-ms-row"><button class="lf-ms-row-head" type="button" :aria-expanded="openId===r.id" @click="openId=openId===r.id?'':r.id"><span><b>{{r.testName}}</b><small>{{r.performedOn}} · {{r.kind}}<span v-if="r.style"> · {{r.style}}</span></small></span><strong>{{primary(r)}}</strong><span>{{openId===r.id?'⌃':'⌄'}}</span></button><template v-if="openId===r.id"><dl><template v-if="r.disciplineName"><dt>Disciplina</dt><dd>{{r.disciplineName}}</dd></template><template v-for="k in ALLOWED[r.sport]" :key="k"><template v-if="r[k]!==null"><dt>{{FIELDS[k].label}}</dt><dd>{{valueLabel(r,k)}}</dd></template></template><template v-if="r.sport==='swim'&&r.distanceM&&r.poolM"><dt>Vasche equivalenti</dt><dd>{{numberLabel(r.distanceM/r.poolM)}}</dd></template><template v-if="metricValue(r,'pace')!==null&&['run','swim'].includes(r.sport)"><dt>Passo medio</dt><dd>{{fmt(r,'pace',metricValue(r,'pace')!)}}</dd></template><template v-if="metricValue(r,'speed')!==null&&['run','cycle','swim'].includes(r.sport)"><dt>Velocità media</dt><dd>{{fmt(r,'speed',metricValue(r,'speed')!)}}</dd></template></dl><p v-if="r.notes" class="lf-ms-notes">{{r.notes}}</p><small class="muted">Inserito da {{r.createdBy===r.athleteId?'Atleta':'Coach'}}{{r.createdBy===actor?' · tu':''}}</small><div v-if="r.createdBy===actor" class="row"><button v-if="!r.archived" class="secondary" type="button" :disabled="!canWrite" @click="newForm(r);openId=''">Modifica</button><button class="secondary" type="button" :disabled="!canWrite" @click="confirmArchive=r">{{r.archived?'Ripristina':'Archivia'}}</button></div><div v-if="confirmArchive?.id===r.id" class="notice"><p>{{r.archived?'Ripristinare il risultato?':'Archiviare il risultato? Non comparirà nei grafici.'}}</p><div class="row"><button type="button" class="primary" :disabled="!canWrite" @click="archive">Conferma</button><button class="secondary" type="button" :disabled="busy" @click="confirmArchive=null">Annulla</button></div></div></template></article></template>
   <section v-else class="panel lf-ms-panel"><label>Indicatore<select v-model="metric"><option v-for="m in choices" :key="m" :value="m">{{metricLabel(m)}}</option></select></label><label>Test comparabile<select v-model="group"><option v-for="[key,r] in groups" :key="key" :value="key">{{groupName(r)}}</option></select></label><p v-if="!example||best===null" class="muted">Nessun dato per questo indicatore.</p><template v-else><div class="lf-ms-record"><small>{{lower(example,metric)?'Valore più basso':'Valore più alto'}} · dati caricati</small><strong>{{fmt(example,metric,best)}}</strong><small>{{points.length}} risultati comparabili</small></div><svg viewBox="0 0 330 175" class="lf-ms-chart" role="img" :aria-label="'Andamento '+metricLabel(metric)"><path d="M30 35H300 M30 90H300 M30 145H300" stroke="var(--border)" stroke-width="1"/><polyline v-if="plot.length>1" :points="plotting" fill="none" stroke="var(--mint)" stroke-width="3"/><circle v-for="p in plot" :key="p.p.r.id" :cx="p.x" :cy="p.y" :r="p.p.r.id===pointId?7:5" fill="var(--mint)" class="lf-ms-dot" @click="pointId=p.p.r.id"><title>{{p.p.r.performedOn}}: {{fmt(p.p.r,metric,p.p.v)}}</title></circle><text x="30" y="167" fill="var(--muted)" font-size="10">{{points[0]?.r.performedOn}}</text><text x="300" y="167" text-anchor="end" fill="var(--muted)" font-size="10">{{points[points.length-1]?.r.performedOn}}</text></svg><p v-if="chosenPoint" class="lf-ms-preview">{{chosenPoint.r.performedOn}} · {{fmt(chosenPoint.r,metric,chosenPoint.v)}}</p><p class="muted small">Confronta soltanto prove con le stesse condizioni. Verifica anche percorso, tecnica e condizioni nelle note.</p><button type="button" class="lf-ms-point" :class="{selected:pointId===p.r.id}" v-for="p in points" :key="p.r.id" @click="pointId=p.r.id"><span>{{p.r.performedOn}}</span><b>{{fmt(p.r,metric,p.v)}}</b></button></template></section>
  </template>
  <button v-if="more" type="button" class="secondary wide" :disabled="loading||busy" @click="pageSize+=100;bind()">Carica altri risultati</button>
 </section>
</template>
<style scoped>
.lf-ms{min-width:0}.lf-ms-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.lf-ms-head h2{margin:5px 0 0;font-size:26px}.lf-ms-head p{margin:5px 0}.lf-ms-symbol{background:var(--green-bg);color:var(--mint);font-size:30px;border-radius:15px;padding:7px 14px}.lf-ms-sports{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.lf-ms-sport{position:relative;text-align:left;min-width:0;border:1px solid var(--border);border-radius:16px;overflow:hidden;color:white;background:linear-gradient(145deg,var(--sport-color),#101b27 78%);min-height:150px;padding:12px;display:flex;flex-direction:column;justify-content:space-between;gap:6px;transition:transform .16s,border-color .16s}.lf-ms-sport:hover{border-color:var(--mint)}.lf-ms-sport:active{transform:scale(.97)}.lf-ms-sport svg{width:90px;height:65px;align-self:flex-end;color:#fff;opacity:.92}.lf-ms-sport-copy{display:flex;flex-direction:column;gap:4px}.lf-ms-sport-copy b{font-size:15px;line-height:1.2}.lf-ms-sport-copy small{font-size:11px;color:#e5edf5}.lf-ms-panel{padding:14px;border-radius:15px}.lf-ms-panel h3{margin:0}.lf-ms-panel label{margin:7px 0;font-size:12px}.lf-ms-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.lf-ms-time{margin:9px 0;border:1px solid var(--border);border-radius:12px;padding:8px;min-width:0}.lf-ms-time legend{font-size:12px;color:var(--muted)}.lf-ms-time>div{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}.lf-ms-time input{padding:7px 5px;text-align:center}.lf-ms-preview,.lf-ms-record{background:var(--green-bg);color:var(--mint);padding:12px;border-radius:12px}.lf-ms-tabs{display:grid;grid-template-columns:1fr 1fr;gap:8px}.lf-ms-tabs button{border:1px solid var(--border);background:var(--card);color:var(--text);border-radius:12px;padding:11px;font-weight:800}.lf-ms-tabs button.on{background:var(--green);color:white}.lf-ms-row{margin:0!important}.lf-ms-row-head{display:flex;width:100%;gap:8px;align-items:center;text-align:left;color:var(--text);background:none;border:0;padding:0}.lf-ms-row-head>span:first-child{flex:1;min-width:0;overflow-wrap:anywhere;display:flex;flex-direction:column;gap:5px}.lf-ms-row-head small{color:var(--muted)}.lf-ms-row-head strong{color:var(--mint);font-size:17px;overflow-wrap:anywhere}.lf-ms-row dl{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:13px 0;font-size:13px}.lf-ms-row dt{color:var(--muted)}.lf-ms-row dd{margin:0;text-align:right;overflow-wrap:anywhere}.lf-ms-row .row{margin-top:10px}.lf-ms-notes{white-space:pre-wrap;overflow-wrap:anywhere}.lf-ms-record{display:grid;gap:5px;margin:12px 0}.lf-ms-record strong{font-size:27px}.lf-ms-chart{width:100%;display:block}.lf-ms-dot{cursor:pointer}.lf-ms-point{width:100%;border:0;background:transparent;color:var(--text);text-align:left;display:flex;justify-content:space-between;gap:6px;border-top:1px solid var(--border);padding:8px 0;font-size:13px}.lf-ms-point.selected{color:var(--mint);background:var(--green-bg)}.lf-ms-panel select,.lf-ms-panel input{min-width:0;width:100%}.lf-ms-panel .checkline input{width:auto}@media(max-width:680px){.lf-ms-sports{grid-template-columns:repeat(2,minmax(0,1fr))}.lf-ms-sport{min-height:142px}.lf-ms-sport-copy b{font-size:14px}}@media(prefers-reduced-motion:reduce){.lf-ms-sport{transition:none}}
</style>
